{"path":"src/normalizer.mjs","oldString":"export function normalizeTransaction(transaction) {
  return {
    id: transaction.id,
    account: transaction.account,
    cents: Math.round(Number(transaction.amount) * 100),
  };
}","newString":"export function normalizeTransaction(transaction) {
  const id = transaction?.id;
  const account = transaction?.account;
  const kind = transaction?.kind;
  const amount = transaction?.amount;
  const validAmount = typeof amount === 'string' && /^\d+(?:\.\d{1,2})?$/.test(amount);
  const [whole = '', fraction = ''] = validAmount ? amount.split('.') : [];
  const unsignedCents = validAmount
    ? Number(whole) * 100 + Number((fraction + '00').slice(0, 2))
    : NaN;

  if (
    typeof id !== 'string' || id.length === 0 ||
    typeof account !== 'string' || account.length === 0 ||
    (kind !== 'credit' && kind !== 'debit') ||
    !Number.isSafeInteger(unsignedCents) || unsignedCents <= 0
  ) {
    throw new TypeError(`Invalid transaction ${String(id)}`);
  }

  return {
    id,
    account,
    cents: kind === 'credit' ? unsignedCents : -unsignedCents,
  };
}"}

